import{_ as t,o,c as a,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"3.2 Authentication & Authorization (9 FRs)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/README.md","filePath":"feature/srs/01-authentication/README.md"}'),s={name:"feature/srs/01-authentication/README.md"};function i(d,e,l,r,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_3-2-authentication-authorization-9-frs" tabindex="-1">3.2 Authentication &amp; Authorization (9 FRs) <a class="header-anchor" href="#_3-2-authentication-authorization-9-frs" aria-label="Permalink to &quot;3.2 Authentication &amp; Authorization (9 FRs)&quot;">​</a></h1><p>&gt; <strong>Navigation:</strong> <a href="./../../README.html">← Feature Master Index</a> · <a href="./../README.html">← SRS 141 FRs Index</a> · <a href="./../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../ba/use-cases/01-authentication-profile.html">Use Cases</a> · <a href="./../../modules/README.html">Module Specs Index</a> · <a href="./../../../rule/feature-workflow.html">Workflow Rule</a></p><p>Canonical specification, technical implementation plan, task breakdown, and unit/acceptance test verification suite for <strong>3.2 Authentication &amp; Authorization</strong> (<code>3.2.1 – 3.2.9</code>, <strong>9 Atomic CRUD Functional Requirements</strong>).</p><hr><h2 id="_1-domain-architecture-overview" tabindex="-1">1. Domain Architecture Overview <a class="header-anchor" href="#_1-domain-architecture-overview" aria-label="Permalink to &quot;1. Domain Architecture Overview&quot;">​</a></h2><p>Authentication and session security in BrandHub span the edge API Gateway, the core Business Service, PostgreSQL identity tables, and Redis ephemeral security state:</p><ul><li><strong>Edge JWT Verification (<code>brandhub-api-gateway</code>):</strong><ul><li><code>JwtAuthFilterGatewayFilterFactory</code> and <code>InboundSecurityWebFilter</code> validate <code>Authorization: Bearer &lt;accessToken&gt;</code> signatures (<code>HS256</code>/<code>RS256</code> via <code>JwtUtil</code>), check Redis token revocation (<code>jwt:blacklist:{jti}</code>), inject verified identity claims (<code>X-User-Id</code>, <code>X-User-Email</code>, <code>X-System-Role</code>), and apply <code>RateLimitGatewayFilterFactory</code> throttling on public auth endpoints.</li></ul></li><li><strong>Core Identity &amp; Credential Engine (<code>brandhub-business-service</code>):</strong><ul><li><strong>Controllers:</strong> <code>AuthController</code> (<code>/api/v1/auth/*</code>), <code>GoogleOAuthController</code> (<code>/api/v1/auth/oauth/google*</code>, <code>/login/oauth2/code/google</code>), <code>AccountActivationController</code> (<code>/api/v1/auth/activation/*</code>).</li><li><strong>Services &amp; Utilities:</strong> <code>AuthServiceImpl</code>, <code>GoogleOAuthService</code>, <code>AccountActivationService</code>, <code>TotpUtil</code> (RFC 6238 HMAC-SHA1 6-digit 30-second window ±1 step), <code>JwtUtil</code> (15-minute Access Token, 30-day Refresh Token rotated via <code>HttpOnly</code> cookie / secure storage, 5-minute <code>type=2fa</code> challenge token), and BCrypt password hashing (cost factor 12).</li></ul></li><li><strong>Persistence &amp; Ephemeral State:</strong><ul><li><strong>PostgreSQL:</strong> <code>users</code>, <code>user_system_roles</code>, <code>user_refresh_tokens</code>, <code>user_oauth_providers</code>, <code>audit_logs</code> (capturing <code>ip_address</code> and <code>user_agent</code>).</li><li><strong>Redis:</strong> <code>otp:attempt:{email}</code>, <code>otp:resend:{email}</code>, <code>phone:otp:{userId}</code>, <code>phone:otp:attempt:{userId}</code>, <code>phone:otp:resend:{userId}</code>, <code>pwd:reset:{token}</code>, <code>pwd:reset:user:{userId}</code>, <code>2fa:setup:{userId}</code>, <code>2fa:attempt:{userId}</code>, <code>oauth:state:{state}</code>, <code>otp:deactivate:{userId}</code>, and <code>jwt:blacklist:{jti}</code>.</li></ul></li><li><strong>Client Surfaces (<code>brandhub-web</code> &amp; <code>brandhub-mobile-app</code>):</strong><ul><li><strong>Web (<code>brandhub-web</code>):</strong> <code>src/pages/auth/{RegisterPage,VerifyOtpPage,LoginPage,OAuthCallbackPage,ForgotPasswordPage,ResetPasswordPage,TwoFactorVerifyPage,ActivateAccountPage}.tsx</code>, <code>src/pages/security/index.tsx</code> (<code>ChangePasswordCard</code>, <code>ActiveSessionsCard</code>), <code>src/pages/profile/index.tsx</code> (Deactivate Account), <code>src/services/authService.ts</code>, <code>src/stores/authStore.ts</code>.</li><li><strong>Mobile (<code>brandhub-mobile-app</code>):</strong> <code>app/(auth)/*</code>, <code>src/screens/settings/{SecuritySettingsScreen,AccountSettingsScreen}.tsx</code>, <code>src/services/authService.ts</code>, <code>src/store/authStore.ts</code> (<code>expo-secure-store</code> token persistence).</li></ul></li></ul><hr><h2 id="_2-functional-requirements-matrix" tabindex="-1">2. Functional Requirements Matrix <a class="header-anchor" href="#_2-functional-requirements-matrix" aria-label="Permalink to &quot;2. Functional Requirements Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">FR ID</th><th style="text-align:left;">UC ID</th><th style="text-align:left;">Function Name</th><th style="text-align:left;">Canonical Roles</th><th style="text-align:left;">Status</th><th style="text-align:left;">Feature Artefacts (<code>spec → plan → task → test</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>3.2.1</code></td><td style="text-align:left;"><code>UC-001</code></td><td style="text-align:left;"><strong>Sign Up</strong></td><td style="text-align:left;"><code>Guest</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-1-sign-up/spec.html">Spec</a> · <a href="./3-2-1-sign-up/plan.html">Plan</a> · <a href="./3-2-1-sign-up/task.html">Task</a> · <a href="./3-2-1-sign-up/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.2</code></td><td style="text-align:left;"><code>UC-002</code></td><td style="text-align:left;"><strong>Sign In with Email</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-2-sign-in-with-email/spec.html">Spec</a> · <a href="./3-2-2-sign-in-with-email/plan.html">Plan</a> · <a href="./3-2-2-sign-in-with-email/task.html">Task</a> · <a href="./3-2-2-sign-in-with-email/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.3</code></td><td style="text-align:left;"><code>UC-003</code></td><td style="text-align:left;"><strong>Sign In with Google OAuth</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-3-sign-in-with-google-oauth/spec.html">Spec</a> · <a href="./3-2-3-sign-in-with-google-oauth/plan.html">Plan</a> · <a href="./3-2-3-sign-in-with-google-oauth/task.html">Task</a> · <a href="./3-2-3-sign-in-with-google-oauth/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.4</code></td><td style="text-align:left;"><code>UC-004</code></td><td style="text-align:left;"><strong>Reset Password</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-4-reset-password/spec.html">Spec</a> · <a href="./3-2-4-reset-password/plan.html">Plan</a> · <a href="./3-2-4-reset-password/task.html">Task</a> · <a href="./3-2-4-reset-password/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.5</code></td><td style="text-align:left;"><code>UC-005</code></td><td style="text-align:left;"><strong>Change Password</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-5-change-password/spec.html">Spec</a> · <a href="./3-2-5-change-password/plan.html">Plan</a> · <a href="./3-2-5-change-password/task.html">Task</a> · <a href="./3-2-5-change-password/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.6</code></td><td style="text-align:left;"><code>UC-006</code></td><td style="text-align:left;"><strong>OTP Verification</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-6-otp-verification/spec.html">Spec</a> · <a href="./3-2-6-otp-verification/plan.html">Plan</a> · <a href="./3-2-6-otp-verification/task.html">Task</a> · <a href="./3-2-6-otp-verification/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.7</code></td><td style="text-align:left;"><code>UC-007</code></td><td style="text-align:left;"><strong>Two-Factor Authentication (2FA, TOTP)</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-7-two-factor-authentication-2fa-totp/spec.html">Spec</a> · <a href="./3-2-7-two-factor-authentication-2fa-totp/plan.html">Plan</a> · <a href="./3-2-7-two-factor-authentication-2fa-totp/task.html">Task</a> · <a href="./3-2-7-two-factor-authentication-2fa-totp/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.8</code></td><td style="text-align:left;"><code>UC-008</code></td><td style="text-align:left;"><strong>Logout</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-8-logout/spec.html">Spec</a> · <a href="./3-2-8-logout/plan.html">Plan</a> · <a href="./3-2-8-logout/task.html">Task</a> · <a href="./3-2-8-logout/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>3.2.9</code></td><td style="text-align:left;"><code>UC-009</code></td><td style="text-align:left;"><strong>Delete Account</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td><td style="text-align:left;">Implemented</td><td style="text-align:left;"><a href="./3-2-9-delete-account/spec.html">Spec</a> · <a href="./3-2-9-delete-account/plan.html">Plan</a> · <a href="./3-2-9-delete-account/task.html">Task</a> · <a href="./3-2-9-delete-account/test.html">Test</a></td></tr></tbody></table><hr><h2 id="_3-core-business-rules-security-invariants" tabindex="-1">3. Core Business Rules &amp; Security Invariants <a class="header-anchor" href="#_3-core-business-rules-security-invariants" aria-label="Permalink to &quot;3. Core Business Rules &amp; Security Invariants&quot;">​</a></h2><ul><li><strong><code>BR-01</code> (Case-Insensitive Unique Email):</strong> Every email input is normalized (<code>trim().toLowerCase(Locale.ROOT)</code>) prior to lookup, registration, OTP verification, or Google OAuth account linking.</li><li><strong><code>BR-02</code> (Password Policy &amp; Hashing):</strong> Minimum 8 characters with at least 1 numeric digit; hashed exclusively with BCrypt (cost 12); plaintext passwords are never persisted or logged.</li><li><strong><code>BR-03</code> &amp; <code>BR-04</code> (Single-Use OTP &amp; Brute-Force Guard):</strong> 6-digit numeric OTP with 10-minute TTL, invalidated after 5 failed attempts (<code>OTP_TOO_MANY_ATTEMPTS</code>) with a 60-second resend cooldown (<code>RATE_LIMIT_EXCEEDED</code>).</li><li><strong><code>BR-05</code> (Account Lifecycle Gate):</strong> Sign-in and token refresh require <code>emailVerifiedAt != null</code> and <code>status == ACTIVE</code>; <code>DEACTIVATED</code> or <code>SUSPENDED</code> accounts are blocked immediately.</li><li><strong><code>BR-08</code> (Session Invalidation on Password Mutation):</strong> Resetting or changing a password stamps <code>users.last_password_change</code>, invalidating all refresh tokens issued prior to that timestamp.</li><li><strong><code>BR-09</code> (QR-Only TOTP 2FA):</strong> RFC 6238 TOTP setup exposes only the <code>otpauth://</code> QR payload (no copyable plaintext secret key and no static backup codes) with 5-attempt lockout protection (<code>2fa:attempt:{userId}</code>).</li><li><strong><code>BR-10</code> &amp; <code>BR-16</code> (Safe Soft Deactivation):</strong> Account deletion soft-deactivates <code>users.status = DEACTIVATED</code>, revokes active tokens, and blocks execution (<code>409 AGENCY_OWNERSHIP_ACTIVE</code>) while the user owns any active Agency.</li></ul><h2 id="_4-cross-references" tabindex="-1">4. Cross-References <a class="header-anchor" href="#_4-cross-references" aria-label="Permalink to &quot;4. Cross-References&quot;">​</a></h2><ul><li><strong>BA Domain Specification:</strong> <a href="./../../../ba/02-authentication-profile.html">02-authentication-profile.md</a></li><li><strong>BA System Overview:</strong> <a href="./../../../ba/README.html">BA Overview</a></li><li><strong>Consolidated Feature Modules:</strong> <a href="./../../modules/README.html">Module Specs Index</a></li></ul>',15)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
